// ===== Read the moisture value from one image =====
async function loadImage(file){
  const url=URL.createObjectURL(file);
  const img=await new Promise((res,rej)=>{const i=new Image(); i.onload=()=>res(i); i.onerror=rej; i.src=url;});
  return {img,url};
}
function toCanvas(img,maxSide){
  const s=Math.min(1,maxSide/Math.max(img.naturalWidth,img.naturalHeight));
  const c=document.createElement('canvas'); c.width=Math.round(img.naturalWidth*s); c.height=Math.round(img.naturalHeight*s);
  c.getContext('2d').drawImage(img,0,0,c.width,c.height); return c;
}
function rgbaToCanvas(o){
  const c=document.createElement('canvas'); c.width=o.width; c.height=o.height;
  c.getContext('2d').putImageData(new ImageData(o.data,o.width,o.height),0,0); return c;
}
async function readWeightImg(img,dec){
  const w=await startEngine();
  const c=toCanvas(img,1000), W=c.width, H=c.height;
  const rgba=c.getContext('2d').getImageData(0,0,W,H).data;
  const r=await MR.readWeight(rgba,W,H,async o=>{const {data}=await w.recognize(rgbaToCanvas(o)); return {text:data.text,confidence:data.confidence};},{decimals:dec});
  if(!r) return null;
  return {value:r.value,conf:r.conf,meter:r.how==='segments'?'LED / 7-segment':'LCD / screen',crop:rgbaToCanvas(r.comp).toDataURL('image/png')};
}
async function readMoisture(img){
  const w=await startEngine();
  const c=toCanvas(img,1000), W=c.width, H=c.height;
  const rgba=c.getContext('2d').getImageData(0,0,W,H).data;
  const blue=MR.looksLikeBlueLCD(rgba);
  let best=null;
  // Try light-on-dark and dark-on-light text, with a global and a local threshold
  for(const method of ['otsu','adaptive']) for(const dark of (blue?[false,true]:[true,false])){
    const f=MR.findReading(MR.inkMask(rgba,W,H,dark,method),W,H); if(!f||f.row.length<3) continue;
    const score=f.h*f.row.length; if(best&&score<=best.score) continue;
    const comp=rgbaToCanvas(MR.composeDigits(f,W,H));
    const {data}=await w.recognize(comp);
    const digits=data.text.replace(/\D/g,'');
    if(digits.length!==f.row.length) continue;
    const dec=MR.chooseDecimals(f,blue);
    const value=MR.formatValue(digits,dec);
    if(value) best={score,value,conf:data.confidence,meter:blue?'Blue LCD (3 dp)':'Colour screen (2 dp)',crop:comp.toDataURL('image/png')};
  }
  return best;
}

